#!/usr/bin/env python3
"""Configure the Android/iOS projects generated by `flutter create` for Rampur Library.

The native folders are generated in CI (so they always match the Flutter version),
then this script applies everything app-specific:

  * application / bundle id, display name, minSdk
  * permissions (notifications, camera, photos) and url_launcher queries
  * Firebase native config files (google-services.json / GoogleService-Info.plist)
    and the Google Services Gradle plugin when they are present
  * iOS URL schemes needed by Firebase Phone Auth (reCAPTCHA fallback)
  * Android release signing when android/key.properties exists
  * iOS push entitlements

Usage: python3 scripts/prepare_mobile.py apps/mobile_app
Env:   APP_ID (default com.rampurlibrary.app), APP_NAME (default "Rampur Library"),
       FIREBASE_IOS_APP_ID, IOS_REVERSED_CLIENT_ID (optional)
"""
import os
import plistlib
import re
import sys
from pathlib import Path

APP_ID = os.environ.get("APP_ID", "com.rampurlibrary.app")
APP_NAME = os.environ.get("APP_NAME", "Rampur Library")
GMS_VERSION = "4.4.2"


def log(msg):
    print(f"[prepare_mobile] {msg}")


def patch_android(app: Path):
    android = app / "android"
    if not android.exists():
        log("no android/ folder, skipping")
        return
    gradle_kts = android / "app" / "build.gradle.kts"
    gradle = gradle_kts if gradle_kts.exists() else android / "app" / "build.gradle"
    kts = gradle.suffix == ".kts"
    s = gradle.read_text()

    # Application id & SDK levels
    s = re.sub(r'applicationId\s*=?\s*"[^"]+"', f'applicationId = "{APP_ID}"' if kts else f'applicationId "{APP_ID}"', s)
    s = re.sub(r"minSdk(Version)?\s*=?\s*[\w.]+", "minSdk = 24" if kts else "minSdkVersion 24", s, count=1)

    # Google services plugin when google-services.json is provided
    has_gms = (android / "app" / "google-services.json").exists()
    if has_gms and "com.google.gms.google-services" not in s:
        s = re.sub(r"plugins\s*\{", 'plugins {\n    id("com.google.gms.google-services")' if kts
                   else "plugins {\n    id \"com.google.gms.google-services\"", s, count=1)
        settings = android / ("settings.gradle.kts" if kts else "settings.gradle")
        st = settings.read_text()
        if "com.google.gms.google-services" not in st:
            line = (f'    id("com.google.gms.google-services") version "{GMS_VERSION}" apply false' if kts
                    else f'    id "com.google.gms.google-services" version "{GMS_VERSION}" apply false')
            # Insert into the top-level `plugins {` block (not pluginManagement)
            idx = [m.start() for m in re.finditer(r"^plugins\s*\{", st, flags=re.M)]
            if idx:
                pos = st.index("{", idx[0]) + 1
                st = st[:pos] + "\n" + line + st[pos:]
                settings.write_text(st)
                log("added google-services plugin to settings")
        log("google-services.json found → Google Services plugin enabled")

    # Release signing from key.properties
    if (android / "key.properties").exists() and "keystoreProperties" not in s:
        if kts:
            header = (
                "import java.util.Properties\nimport java.io.FileInputStream\n\n"
                "val keystoreProperties = Properties()\n"
                'val keystorePropertiesFile = rootProject.file("key.properties")\n'
                "if (keystorePropertiesFile.exists()) { keystoreProperties.load(FileInputStream(keystorePropertiesFile)) }\n\n"
            )
            signing = (
                "    signingConfigs {\n"
                '        create("release") {\n'
                '            keyAlias = keystoreProperties["keyAlias"] as String\n'
                '            keyPassword = keystoreProperties["keyPassword"] as String\n'
                '            storeFile = file(keystoreProperties["storeFile"] as String)\n'
                '            storePassword = keystoreProperties["storePassword"] as String\n'
                "        }\n"
                "    }\n\n"
                "    buildTypes {"
            )
            s = header + s
            s = s.replace("    buildTypes {", signing, 1)
            s = s.replace('signingConfig = signingConfigs.getByName("debug")', 'signingConfig = signingConfigs.getByName("release")')
        else:
            header = (
                "def keystoreProperties = new Properties()\n"
                "def keystorePropertiesFile = rootProject.file('key.properties')\n"
                "if (keystorePropertiesFile.exists()) { keystoreProperties.load(new FileInputStream(keystorePropertiesFile)) }\n\n"
            )
            signing = (
                "    signingConfigs {\n        release {\n"
                "            keyAlias keystoreProperties['keyAlias']\n            keyPassword keystoreProperties['keyPassword']\n"
                "            storeFile file(keystoreProperties['storeFile'])\n            storePassword keystoreProperties['storePassword']\n"
                "        }\n    }\n\n    buildTypes {"
            )
            s = header + s
            s = s.replace("    buildTypes {", signing, 1)
            s = s.replace("signingConfig signingConfigs.debug", "signingConfig signingConfigs.release")
        log("release signing configured from key.properties")
    gradle.write_text(s)

    # Manifest: label, permissions, queries
    manifest = android / "app" / "src" / "main" / "AndroidManifest.xml"
    m = manifest.read_text()
    m = re.sub(r'android:label="[^"]*"', f'android:label="{APP_NAME}"', m, count=1)
    perms = [
        "android.permission.INTERNET",
        "android.permission.POST_NOTIFICATIONS",
        "android.permission.CAMERA",
        "android.permission.VIBRATE",
    ]
    for p in perms:
        if p not in m:
            m = m.replace("<application", f'<uses-permission android:name="{p}" />\n    <application', 1)
    if 'android:scheme="https"' not in m:
        queries = (
            "        <intent>\n            <action android:name=\"android.intent.action.VIEW\" />\n"
            "            <data android:scheme=\"https\" />\n        </intent>\n"
            "        <intent>\n            <action android:name=\"android.intent.action.DIAL\" />\n"
            "            <data android:scheme=\"tel\" />\n        </intent>\n"
            "        <intent>\n            <action android:name=\"android.intent.action.SENDTO\" />\n"
            "            <data android:scheme=\"mailto\" />\n        </intent>\n"
        )
        if "<queries>" in m:
            m = m.replace("<queries>", "<queries>\n" + queries, 1)
        else:
            m = m.replace("</manifest>", "    <queries>\n" + queries + "    </queries>\n</manifest>")
    if "default_notification_channel_id" not in m:
        meta = ('        <meta-data android:name="com.google.firebase.messaging.default_notification_channel_id"'
                ' android:value="library_updates" />\n')
        m = m.replace("</application>", meta + "    </application>", 1)
    manifest.write_text(m)

    # Channel name shown in Android settings
    values = android / "app" / "src" / "main" / "res" / "values"
    values.mkdir(parents=True, exist_ok=True)
    (values / "strings.xml").write_text(
        '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n'
        f'    <string name="app_name">{APP_NAME}</string>\n'
        "</resources>\n"
    )
    log(f"android configured: {APP_ID}")


def patch_ios(app: Path):
    ios = app / "ios"
    plist_path = ios / "Runner" / "Info.plist"
    if not plist_path.exists():
        log("no ios/Runner/Info.plist, skipping")
        return
    with open(plist_path, "rb") as f:
        info = plistlib.load(f)

    info["CFBundleDisplayName"] = APP_NAME
    info["CFBundleName"] = APP_NAME
    info["NSCameraUsageDescription"] = "Scan the ISBN barcode on a book to find it in the library."
    info["NSPhotoLibraryUsageDescription"] = "Choose a profile photo for your membership card."
    modes = set(info.get("UIBackgroundModes", []))
    modes.update(["remote-notification", "fetch"])
    info["UIBackgroundModes"] = sorted(modes)
    info["FirebaseAppDelegateProxyEnabled"] = True
    info["ITSAppUsesNonExemptEncryption"] = False

    schemes = []
    reversed_id = os.environ.get("IOS_REVERSED_CLIENT_ID", "")
    gsi = ios / "Runner" / "GoogleService-Info.plist"
    if gsi.exists():
        with open(gsi, "rb") as f:
            reversed_id = plistlib.load(f).get("REVERSED_CLIENT_ID", reversed_id)
    if reversed_id:
        schemes.append(reversed_id)
    ios_app_id = os.environ.get("FIREBASE_IOS_APP_ID", "")
    if ios_app_id:
        schemes.append("app-" + ios_app_id.replace(":", "-"))
    if schemes:
        info["CFBundleURLTypes"] = [{"CFBundleTypeRole": "Editor", "CFBundleURLSchemes": schemes}]
        log(f"iOS URL schemes for phone auth: {schemes}")
    else:
        log("WARNING: no REVERSED_CLIENT_ID / FIREBASE_IOS_APP_ID — phone auth reCAPTCHA fallback will not work on iOS")

    with open(plist_path, "wb") as f:
        plistlib.dump(info, f)

    # Push notifications entitlement
    ent = ios / "Runner" / "Runner.entitlements"
    with open(ent, "wb") as f:
        plistlib.dump({"aps-environment": os.environ.get("APS_ENVIRONMENT", "production")}, f)

    pbx = ios / "Runner.xcodeproj" / "project.pbxproj"
    p = pbx.read_text()
    p = re.sub(r"PRODUCT_BUNDLE_IDENTIFIER = [^;]*RunnerTests;", f"PRODUCT_BUNDLE_IDENTIFIER = {APP_ID}.RunnerTests;", p)
    p = re.sub(r"PRODUCT_BUNDLE_IDENTIFIER = (?![^;]*RunnerTests)[^;]+;", f"PRODUCT_BUNDLE_IDENTIFIER = {APP_ID};", p)
    if "CODE_SIGN_ENTITLEMENTS" not in p:
        p = p.replace(f"PRODUCT_BUNDLE_IDENTIFIER = {APP_ID};",
                      f"PRODUCT_BUNDLE_IDENTIFIER = {APP_ID};\n\t\t\t\tCODE_SIGN_ENTITLEMENTS = Runner/Runner.entitlements;")
    p = re.sub(r"IPHONEOS_DEPLOYMENT_TARGET = [\d.]+;", "IPHONEOS_DEPLOYMENT_TARGET = 15.0;", p)
    pbx.write_text(p)
    log(f"ios configured: {APP_ID}")


if __name__ == "__main__":
    app_dir = Path(sys.argv[1] if len(sys.argv) > 1 else "apps/mobile_app")
    patch_android(app_dir)
    patch_ios(app_dir)
